SELECT n.profile AS p, c.section_id = 'PROCEDURE' AS at_root, c.field_id AS f, count(*) AS k FROM notices n JOIN notice_codes c ON c.notice_id = n.id AND c.field_id IN ('BT-23-Lot', 'BT-23-Procedure') WHERE n.id IN (SELECT id FROM (SELECT id FROM notices WHERE profile = 'eforms:eforms-sdk-1.3' ORDER BY id DESC LIMIT 40) UNION ALL SELECT id FROM (SELECT id FROM notices WHERE profile = 'eforms:eforms-sdk-1.7' ORDER BY id DESC LIMIT 40) UNION ALL SELECT id FROM (SELECT id FROM notices WHERE profile = 'eforms:eforms-sdk-1.10' ORDER BY id DESC LIMIT 40) UNION ALL SELECT id FROM (SELECT id FROM notices WHERE profile = 'eforms:eforms-de-2.1' ORDER BY id DESC LIMIT 40)) GROUP BY 1, 2, 3 UNION ALL SELECT n.profile, t.section_id = 'PROCEDURE', t.field_id, count(*) FROM notices n JOIN notice_texts t ON t.notice_id = n.id AND t.field_id IN ('DE1-ProcurementProject-Name', 'DE1-ProcurementProjectLot-ProcurementProject-Name') WHERE n.id IN (SELECT id FROM notices WHERE profile = 'eforms:eforms-de-1.2' ORDER BY id DESC LIMIT 40) GROUP BY 1, 2, 3
